SELECT COUNT(*)
  FROM doctor_schedule_request
 WHERE doctor_id = #{doctorId}
   AND status = 0
   AND schedule_date = #{scheduleDate}
   AND period = #{period}

   AND (target_schedule_id IS NULL OR target_schedule_id <> #{targetScheduleId})

SELECT FROM doctor_schedule_request r JOIN doctor d ON d.id = r.doctor_id JOIN department dp ON dp.id = r.department_id LEFT JOIN sys_user u ON u.id = r.reviewed_by_user_id WHERE r.doctor_id = #{doctorId}
AND r.status = #{status}
ORDER BY r.created_at DESC

SELECT 
  FROM doctor_schedule_request r
  JOIN doctor d ON d.id = r.doctor_id
  JOIN department dp ON dp.id = r.department_id
  LEFT JOIN sys_user u ON u.id = r.reviewed_by_user_id
 WHERE 1 = 1

   AND (


         EXISTS (
           SELECT 1
             FROM department_manager dm
            WHERE dm.department_id = r.department_id
              AND dm.user_id = #{operatorUserId}
         )


         1 = 0



       OR r.department_id = #{operatorDepartmentId}

   )


   AND r.department_id = #{departmentId}


   AND r.status = #{status}

 ORDER BY CASE WHEN r.status = 0 THEN 0 ELSE 1 END, r.created_at DESC

SELECT *
  FROM doctor_schedule_request
 WHERE id = #{id}
   AND doctor_id = #{doctorId}
   FOR UPDATE

SELECT COUNT(*)
  FROM department_manager
 WHERE user_id = #{userId}
   AND department_id = #{departmentId}

mapper.update:
UPDATE doctor_schedule_request
   SET status = 2,
       reviewed_by_user_id = #{operatorUserId},
       reviewed_at = CURRENT_TIMESTAMP,
       review_remark = #{reviewRemark}
 WHERE id = #{id}
